<template>
  <svg :class="['logo', { play: animated }]" viewBox="80 540 680 207" role="img" aria-label="AIMfocus logo" @animationend="onAnimationEnd">
    <defs>
      <image id="afsr-art-logo" width="1536" height="1024" :href="imageData" />
      <clipPath id="afsr-o-logo"><circle cx="450" cy="620" r="43"/></clipPath>
      <mask id="afsr-rest-logo"><rect x="0" y="0" width="1536" height="1024" fill="white"/><circle cx="450" cy="620" r="44" fill="black"/></mask>
    </defs>
    <use href="#afsr-art-logo" mask="url(#afsr-rest-logo)"/>
    <g class="shutter"><use href="#afsr-art-logo" clip-path="url(#afsr-o-logo)"/></g>
  </svg>
</template>

<script setup>
import { ref, onMounted } from 'vue'

const emit = defineEmits(['animation-done'])

const animated = ref(false)

const imageData = 'data:image/png;base64,'

onMounted(() => {
  // Small delay so the logo renders before the animation starts
  setTimeout(() => { animated.value = true }, 100)
})

function onAnimationEnd() {
  emit('animation-done')
}
</script>

<style scoped>
.logo {
  display: block;
  width: 100%;
  height: auto;
}
.shutter {
  transform-origin: 450px 620px;
}
.logo.play .shutter {
  animation: e-turn 1600ms cubic-bezier(.35, 0, .2, 1) both;
}
@keyframes e-turn {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(90deg); }
}
@media (prefers-reduced-motion: reduce) {
  .logo.play .shutter { animation: none; }
}
</style>
